Account source = new Account(Id = '001B000001DVM9tIAH', Name = 'Acme');
System.assertEquals(false, source.isClone());
System.assertEquals(null, source.getCloneSourceId());
Account cloneNoId = source.clone(false, true, false, false);
System.assertEquals(true, cloneNoId.isClone());
System.assertEquals(source.get('Id'), cloneNoId.getCloneSourceId());
System.assertEquals(null, cloneNoId.get('Id'));
Account cloneWithId = source.clone(true, true, false, false);
System.assertEquals(true, cloneWithId.isClone());
System.assertEquals(source.get('Id'), cloneWithId.get('Id'));
System.assertEquals(source.get('Id'), cloneWithId.getCloneSourceId());

